"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["8473"],{55306(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.cardinalidade_obrigatoria","status":422,"titulo":"Cardinalidade do fato \xe9 obrigat\xf3ria"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.cardinalidade_obrigatoria","requisitos":["UNI-REQ-0143","UNI-REQ-0159"],"oQueAconteceu":["A cardinalidade, que diz se o fato aceita uma resposta ou v\xe1rias, \xe9 um dos eixos do fato declarado (UNI-REQ-0143). O cadastro (`POST /api/configuracao/admin/fatos-candidato`) chegou com a `cardinalidade` vazia ou s\xf3 com espa\xe7os, ou a altera\xe7\xe3o da defini\xe7\xe3o (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`) de um fato declarado chegou sem ela. Na altera\xe7\xe3o, todos os eixos do fato declarado s\xe3o enviados de novo, e o que n\xe3o vem \xe9 tratado como n\xe3o informado.","A recusa vem na lista `errors` da resposta, com `field` igual a `cardinalidade`. Nada \xe9 gravado. Uma cardinalidade preenchida e desconhecida recebe [a recusa de cardinalidade fora do vocabul\xe1rio](/erros/uniplus.configuracao.fato_candidato.cardinalidade_invalida). O campo ausente do corpo do cadastro \xe9 recusado antes, como erro de requisi\xe7\xe3o (400)."],"comoResolver":["Informe `VALOR_UNICO` (uma \xfanica resposta) ou `VARIOS_VALORES` (v\xe1rias respostas). O fato derivado por regra e o resumo de grupo n\xe3o informam a cardinalidade, e por isso n\xe3o recebem esta recusa."],"ondeAparece":["Cadastro de um fato declarado do cat\xe1logo","Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);